{"packet_id":"D032-01","doc_id":"D032","jurisdiction":"Hoboken, NJ","category":"rent_increase_limits","lifecycle":"enacted","title":"Hoboken Rent Leveling and Stabilization Ordinance rent control","requirement":"Rents are controlled at the October 1, 1985 base rent; no increase may be demanded, paid or accepted except as the chapter allows, and a landlord must give 30 days' written notice before any increase. Excess increases are void and must be refunded.","key_value":"base rent as of October 1, 1985; 30 days' notice","coverage_conditions":"All dwelling units in Hoboken, except motels/hotels, industrial and commercial property, school and government housing, first rental of newly constructed dwellings, buildings vacant since January 1, 1984, and multiple dwellings constructed after June 25, 1987.","applicability":{"conditions":[{"type":"built_within_years","role":"exempt","years":30,"basis":"construction","conditional":true},{"type":"other","text":"building completely vacant on or before and since January 1, 1984"},{"type":"owner","role":"exempt","who":"state or federal government agencies","unit_limit":null}],"per_tenancy":"Newly constructed dwellings are exempt for their initial rent or lease agreement; all subsequent rents are subject.","coverage_quotes":["This chapter shall apply to all dwelling units as defined in § 155-1 above, except that the following shall be exempt:","In accordance with N.J.S.A. 2A:42-84.1 et seq., the provisions of this chapter shall not apply to multiple dwellings, as defined in the statute, constructed after June 25, 1987, for a period not to exceed the period of amortization of any initial mortgage loan obtained for the multiple dwelling or for 30 years following completion of construction, whichever is less.","Housing owned and operated by other government agencies, such as the state or federal government."]},"exemptions":"Motels and hotels; first rental of newly constructed dwellings; industrial property; nonresidential and commercial property; school, college or institution student housing; state or federal government housing; buildings vacant since January 1, 1984; multiple dwellings constructed after June 25, 1987 (N.J.S.A. 2A:42-84.1).","penalty":"Any rent increase in excess of that authorized is void, and excess rents must be refunded or credited to the tenant; a two-year statute of limitations and two-year period of repose limit recovery.","effective_date":null,"valid_through":null,"citation":"Hoboken City Code § 155-4","quoted_span":"All rents for rental of housing space and services in dwellings to which this act is applicable are hereby controlled at the base rent level received by the landlord as of October 1, 1985, and no rental increases shall be hereinafter demanded, paid or accepted, except as provided in this chapter.","interaction":"Application of this chapter is preempted while a contract gives a governmental agency authority to regulate rents that supersedes the City's; the chapter resumes when the contract ends.","relations":[],"confidence":0.9,"conflict_flag":false,"conflict_note":null}
{"packet_id":"D032-01","doc_id":"D032","jurisdiction":"Hoboken, NJ","category":"just_cause_eviction","lifecycle":"enacted","title":"Hoboken rent ordinance just cause for eviction definition","requirement":"Under the chapter, 'just cause for eviction' means the landlord recovered possession of a housing space or dwelling for one of the reasons outlined in New Jersey State law (N.J.S.A. 2A:18-53 as amended).","key_value":null,"coverage_conditions":"All dwelling units covered by Chapter 155, subject to the exemptions in § 155-2.","applicability":{"conditions":[],"per_tenancy":null,"coverage_quotes":[]},"exemptions":null,"penalty":null,"effective_date":null,"valid_through":null,"citation":"Hoboken City Code § 155-1","quoted_span":"JUST CAUSE FOR EVICTION — The landlord recovered possession of a housing space or dwelling for one of the reasons outlined in New Jersey State law (N.J.S.A. 2A:18-53 as amended).","interaction":null,"relations":[],"confidence":0.5,"conflict_flag":false,"conflict_note":null}
